INSERT INTO courses(id,title,start_date,end_date,duration_weeks,timezone,regular_price,early_price,early_deadline) VALUES ('ai-web-2026','AI-Powered Web Development Bootcamp','2026-11-09','2026-12-18',6,'Africa/Nairobi',1000000,800000,'2026-11-01T20:59:59.999Z');
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-1','ai-web-2026','Think like a builder','Web foundations, AI coding agents, IDE setup, planning and prompting.',1);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-1','week-1','Think like a builder','Web foundations, AI coding agents, IDE setup, planning and prompting.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-1-1','module-1','How the web fits together','Explain the browser, server, HTML, CSS, JavaScript and HTTP.','Explain the browser, server, HTML, CSS, JavaScript and HTTP.','Draw the journey from a URL to a rendered page. Identify the frontend, backend and database of three familiar websites. Ask your agent to explain the requests in your browser network panel. Verify its explanation against what you observe.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-1-1','ai-web-2026','lesson-1-1','How the web fits together — practice','A diagram of your project’s users, screens and data.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-1-2','module-1','Your agent, your environment','Set up an IDE and write a useful project brief.','Set up an IDE and write a useful project brief.','Install your chosen editor and coding agent using official instructions. Create a folder and a version-controlled repository. Write a brief describing your audience, problem, pages, acceptance criteria and constraints. Give your agent one small task at a time; inspect its changes before accepting them. Never put API keys into prompts or committed files.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-1-2','ai-web-2026','lesson-1-2','Your agent, your environment — practice','A project brief with measurable acceptance criteria.',2);
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-2','ai-web-2026','Give your idea a face','Frontend interfaces, design principles and responsive components.',2);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-2','week-2','Give your idea a face','Frontend interfaces, design principles and responsive components.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-2-1','module-2','Design a coherent interface','Create an accessible layout, typography scale and component system.','Create an accessible layout, typography scale and component system.','Sketch the mobile layout first. Choose a limited color palette and type scale. Ask your agent to build semantic navigation, buttons and form fields. Check heading order, focus visibility and color contrast yourself. Test empty, loading and error states before adding decorative motion.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-2-1','ai-web-2026','lesson-2-1','Design a coherent interface — practice','A mobile-first homepage with reusable components.',3);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-2-2','module-2','Responsive by intention','Adapt components to phones, tablets and desktops.','Adapt components to phones, tablets and desktops.','Use flexible grids, relative sizing and content-driven breakpoints. Inspect at 360, 768 and 1440 pixels. Check long text, large text and keyboard navigation. Ask your agent to explain every breakpoint and remove fixed widths that cause horizontal scrolling.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-2-2','ai-web-2026','lesson-2-2','Responsive by intention — practice','Screenshots and a checklist of responsive fixes.',4);
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-3','ai-web-2026','Make it actually work','Backend concepts, APIs, databases, forms and authentication.',3);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-3','week-3','Make it actually work','Backend concepts, APIs, databases, forms and authentication.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-3-1','module-3','From a form to a database','Validate input server-side and store it safely.','Validate input server-side and store it safely.','Model your entities and their relationships. Use parameterized queries and database constraints. Trace a form submission through validation, authorization, persistence and response. Intentionally submit invalid and duplicate data; check the errors and stored records.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-3-1','ai-web-2026','lesson-3-1','From a form to a database — practice','A working validated form backed by a database.',5);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-3-2','module-3','Identity and permissions','Distinguish authentication from authorization.','Distinguish authentication from authorization.','Use an established authentication approach. Keep secrets on the server. Protect every data access by the current user and test with two accounts. Add appropriate session expiry and secure cookies. Ask your agent to identify CSRF and XSS risks, then verify the proposed protections.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-3-2','ai-web-2026','lesson-3-2','Identity and permissions — practice','A private page with ownership checks.',6);
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-4','ai-web-2026','Take it to the world','Git, GitHub, Cloudflare, domains, DNS, HTTPS and deployment.',4);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-4','week-4','Take it to the world','Git, GitHub, Cloudflare, domains, DNS, HTTPS and deployment.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-4-1','module-4','Version your work','Use commits, branches and code review to keep changes understandable.','Use commits, branches and code review to keep changes understandable.','Inspect a diff before committing. Write a commit message that explains the change. Create a branch and pull request. Practice reverting a small change without deleting the repository. Verify that secret files and generated output are ignored.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-4-1','ai-web-2026','lesson-4-1','Version your work — practice','A repository with readable commits and a reviewed branch.',7);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-4-2','module-4','Deploy with confidence','Deploy a compatible app and understand domains and HTTPS.','Deploy a compatible app and understand domains and HTTPS.','Build locally and test in the target runtime. Configure bindings and secrets in the hosting platform. Deploy a preview first. For a custom domain, follow your registrar and Cloudflare DNS instructions, verify HTTPS and redirects, and keep a rollback plan. Domain purchases and paid usage are separate costs.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-4-2','ai-web-2026','lesson-4-2','Deploy with confidence — practice','A deployed website and an operator checklist.',8);
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-5','ai-web-2026','Build for the real world','SEO, Search Console, performance, accessibility and security.',5);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-5','week-5','Build for the real world','SEO, Search Console, performance, accessibility and security.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-5-1','module-5','Help the right people find you','Create useful metadata and public search discovery.','Create useful metadata and public search discovery.','Give each public page a descriptive title, description and canonical URL. Create a sitemap and robots file. Keep private routes out of indexing. Verify domain ownership in Search Console and submit the sitemap. Submission helps discovery but never guarantees indexing.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-5-1','ai-web-2026','lesson-5-1','Help the right people find you — practice','A public SEO checklist and a private-route indexing audit.',9);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-5-2','module-5','Quality is a feature','Test performance, accessibility and security.','Test performance, accessibility and security.','Inspect loading behavior and reduce unnecessary scripts. Navigate using only a keyboard. Test form validation, user permissions, broken links and failed network requests. Ask your agent for meaningful tests derived from acceptance criteria. Review dependencies and avoid logging private data.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-5-2','ai-web-2026','lesson-5-2','Quality is a feature — practice','A prioritized quality report with verified fixes.',10);
INSERT INTO weeks(id,course_id,title,description,position) VALUES('week-6','ai-web-2026','Launch your own thing','Capstone integration, debugging, testing, deployment and presentations.',6);
INSERT INTO modules(id,week_id,title,description,position) VALUES('module-6','week-6','Launch your own thing','Capstone integration, debugging, testing, deployment and presentations.',1);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-6-1','module-6','Integrate and investigate','Connect your project end to end and debug from evidence.','Connect your project end to end and debug from evidence.','Revisit the project brief. Test each user journey with realistic data. Reproduce problems, collect evidence, form a hypothesis and change one thing at a time. Review agent-generated diffs. Keep scope achievable and document unresolved issues honestly.',1,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-6-1','ai-web-2026','lesson-6-1','Integrate and investigate — practice','A tested release candidate and a short maintenance guide.',11);
INSERT INTO lessons(id,module_id,title,description,outcomes,content,position,published) VALUES('lesson-6-2','module-6','Ship, showcase, keep learning','Launch your capstone and explain its tradeoffs.','Launch your capstone and explain its tradeoffs.','Run your deployment checklist, verify production routes, and demonstrate the problem your site solves. Explain what the AI helped with, what you verified, and what needs future maintenance. Share your deployed URL and repository where appropriate.',2,1);
INSERT INTO assignments(id,course_id,lesson_id,title,description,position) VALUES('assignment-6-2','ai-web-2026','lesson-6-2','Ship, showcase, keep learning — practice','A deployed capstone and a five-minute walkthrough.',12);
